// Some portions generated by Codex
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');
const scripts = require('./workbench-scripts.js').compiledScriptsDir();
const context = vm.createContext({ workbench: {} });
installDetailDisclosureTemplateRuntime(context.workbench);
vm.runInContext(fs.readFileSync(path.join(scripts, 'workbenchViews.js'), 'utf8'), context);
const vocabulary = context.workbench.configurationVocabulary;
const config = 'tag:rdf4j.org,2023:config/';
const fixtures = JSON.parse(fs.readFileSync(path.join(__dirname, '../../../test/resources/'
    + 'org/eclipse/rdf4j/workbench/commands/config-reference-prefix-cases.json'), 'utf8'));

for (const fixture of fixtures) {
    test('shared Rio semantic fixture: ' + fixture.name, () => {
        const plan = vocabulary.plan(fixture.source, fixture.iris, [fixture.fragment]);
        assert.equal(plan.added, fixture.added);
        const expected = fixture.source.startsWith('\uFEFF')
            ? '\uFEFF' + fixture.added + fixture.source.slice(1) : fixture.added + fixture.source;
        assert.equal(plan.turtle, expected, 'only the missing declarations are inserted, after an initial BOM');
        assert.equal(plan.compact(fixture.fragment), fixture.compact);
        const repeated = vocabulary.plan(plan.turtle, fixture.iris, [fixture.fragment]);
        assert.equal(repeated.added, '', 'repeated reconciliation never creates more declarations or aliases');
        assert.equal(repeated.compact(fixture.fragment), fixture.compact);
    });
}

for (const draft of [
    '[] config:undefined "invalid" .',
    '@prefix config: <unfinished',
    '@prefix config <urn:foreign:> .',
    'PREFIX config',
    '@prefix config: <relative/> . [] config:value "relative" .',
    '@prefix config: <urn:first:> . @prefix config: <urn:second:> .',
    '[] <urn:query> """unfinished PREFIX config: <urn:fake:>'
]) {
    test('invalid or contextual draft is preserved: ' + draft, () => {
        const plan = vocabulary.plan(draft, [config + 'setting']);
        assert.equal(plan.turtle.slice(plan.added.length), draft);
        assert.equal(vocabulary.plan(plan.turtle, [config + 'setting']).added, '');
        if (!draft.includes('"""')) { assert.equal(plan.iri(config + 'setting'), 'config1:setting'); }
    });
}

test('deleted and rebound prefixes produce a stable fresh mapping without claiming undefined uses', () => {
    const original = '@prefix config: <' + config + '> .\n[] config:setting "body" .\n';
    const deleted = original.slice(original.indexOf('\n') + 1);
    const restored = vocabulary.plan(deleted, [config + 'setting']);
    assert.equal(restored.iri(config + 'setting'), 'config1:setting');
    assert.match(restored.turtle, /^@prefix config1:/);
    assert.ok(restored.turtle.endsWith(deleted));
    const rebound = original.replace('<' + config + '>', '<urn:foreign:>');
    const repaired = vocabulary.plan(rebound, [config + 'setting']);
    assert.equal(repaired.iri(config + 'setting'), 'config1:setting');
    assert.ok(repaired.turtle.endsWith(rebound));
    assert.equal(vocabulary.plan(repaired.turtle, [config + 'setting']).added, '');
});

test('only displayed vocabulary and example IRIs require declarations', () => {
    const plan = vocabulary.reference('', [{ id: 'sail', type: 'openrdf:MemoryStore', options: [{
        predicate: config + 'setting', description: 'Setting', valueType: 'resource',
        datatype: 'urn:hidden:datatype', aliases: ['urn:hidden:legacy'], examples: ['<urn:visible:value>']
    }] }]);
    assert.doesNotMatch(plan.added, /hidden|openrdf/);
    assert.match(plan.added, /urn:visible:/);
    assert.equal(plan.iri('urn:visible:value'), 'ns:value');
});

for (const name of ['config', 'xsd']) {
    test('undefined datatype QName prefix is reserved: ' + name, () => {
        const namespace = name === 'config' ? config : 'http://www.w3.org/2001/XMLSchema#';
        const draft = '[] <urn:p> "value"^^' + name + ':Type .';
        const plan = vocabulary.plan(draft, [namespace + 'setting']);
        assert.equal(plan.iri(namespace + 'setting'), name + '1:setting');
        assert.ok(plan.turtle.endsWith(draft));
        assert.doesNotMatch(plan.added, new RegExp('@prefix ' + name + ':'));
    });
}
